(()=>{'use strict';
const $=id=>document.getElementById(id),M=SplitPlotModel,c=CATALOG.find(c=>c.id==='splitplot');
const hints=['灌水难改变，先在较大的主区实施；施肥可以细分。','每个区组分成两个主区，用区组控制田间差异。','每区组内随机分配 W1、W2，一次分配决定整个主区。','每个主区分三份，再独立随机分配 F1、F2、F3。','整主区灌水，副区分别施肥；田埂用于隔离水分。','点击副区查看模拟响应；比较时尊重两级实验单元。','灌水用主区误差；施肥及交互作用用副区误差。'];
const state={step:0,design:M.design(3),data:M.observations(3),mainPositions:Array.from({length:3},()=>[0,1]),subPositions:Array.from({length:3},()=>Array.from({length:2},()=>[0,1,2])),compare:'water',selected:null,hitRegions:[]};
const stats=M.anova(state.data),world=new PlantWorld.World($('scene'),{extent:20.5,target:.7,pitch:.66,yaw:-.3});
world.draw=w=>{state.hitRegions=[];SplitPlotWorld.draw(w,state)};
world.update=dt=>{state.design.forEach((d,r)=>{for(let water=0;water<2;water++){const target=state.step<2?water:d.water.indexOf(water);state.mainPositions[r][water]+=(target-state.mainPositions[r][water])*Math.min(1,dt*4.5);for(let f=0;f<3;f++){const col=state.step<3?f:d.fertilizer[water].indexOf(f);state.subPositions[r][water][f]+=(col-state.subPositions[r][water][f])*Math.min(1,dt*5)}}})};
world.onInteract=()=>{$('rotate').setAttribute('aria-pressed','false')};
document.title='裂区试验设计 · 灌水主区 × 施肥副区';$('title').textContent=c.title;$('stage-keyword').textContent='主区：灌水 2 水平 · 副区：施肥 3 水平';
c.steps.forEach((title,i)=>{const b=document.createElement('button');b.innerHTML=`<span>${String(i+1).padStart(2,'0')}</span>${title}`;b.onclick=()=>{stop();setStep(i)};$('steps').append(b)});
$('controls').innerHTML='<button class="randomize" id="random-main">主区随机 ↻</button><button class="randomize secondary" id="random-sub">副区随机 ↻</button>';
const panel=document.createElement('aside');panel.className='split-analysis';panel.id='analysis';panel.hidden=true;panel.setAttribute('aria-label','比较与误差分析');panel.innerHTML='<div class="compare-tabs" role="group" aria-label="选择要比较的效应"><button data-effect="water">灌水 A</button><button data-effect="fertilizer">施肥 B</button><button data-effect="interaction">A × B</button></div><div id="analysis-content"></div><details id="anova-details"><summary>查看方差分析表</summary><table><thead><tr><th>来源</th><th>df</th><th>MS</th><th>F</th></tr></thead><tbody id="anova-rows"></tbody></table><p class="table-note">平衡随机区组裂区模型 · 数值为模拟</p></details>';document.querySelector('.stage').append(panel);
const legend=document.createElement('div');legend.className='split-legend';legend.id='legend';legend.innerHTML='<span class="wkey">W1 低灌水 · W2 高灌水</span><span><i style="background:#c8b16f"></i>F1 <i style="background:#96ae79"></i>F2 <i style="background:#b88e72"></i>F3</span>';document.querySelector('.stage').append(legend);
let auto=false,timer=null;
function setStep(n){state.step=Math.max(0,Math.min(c.steps.length-1,n));state.selected=null;update()}
function update(){document.querySelectorAll('#steps button').forEach((b,i)=>{b.classList.toggle('active',i===state.step);b.setAttribute('aria-current',i===state.step?'step':'false')});$('steps').children[state.step].scrollIntoView({block:'nearest',inline:'nearest'});$('caption').textContent=hints[state.step];$('description').textContent=hints[state.step];$('progress').textContent=`${state.step+1} / ${c.steps.length}`;$('prev').disabled=state.step===0;$('next').disabled=state.step===c.steps.length-1;$('random-main').disabled=state.step<2;$('random-sub').disabled=state.step<3;$('legend').hidden=state.step<2;$('analysis').hidden=state.step<5;
 $('readout').textContent=state.step===6?(state.compare==='water'?'灌水每水平 3 个独立主区，不是 9 次重复':'施肥及交互：副区误差 df = 8'):'3 区组 × 2 主区 × 3 副区 = 18 副区';$('scene').dataset.step=state.step;$('scene').setAttribute('aria-label',`裂区试验立体场景。${hints[state.step]}。拖动旋转、滚轮缩放。`);renderAnalysis()}
function renderAnalysis(){document.querySelectorAll('[data-effect]').forEach(b=>{b.classList.toggle('active',b.dataset.effect===state.compare);b.setAttribute('aria-pressed',String(b.dataset.effect===state.compare))});const effect=stats.rows.find(r=>r.id===state.compare),den=stats.rows.find(r=>r.id===effect.denominator);if(state.step===5){const means=stats.means;if(state.compare==='water')$('analysis-content').innerHTML=`<div class="analysis-title">比较灌水：先看主区均值</div><div class="mean-pair"><span>W1 <b>${(means[0].reduce((a,b)=>a+b)/3).toFixed(1)}</b></span><span>W2 <b>${(means[1].reduce((a,b)=>a+b)/3).toFixed(1)}</b></span></div><p>每个主区的 3 个副区均值，代表一个灌水实验单元。</p>`;else if(state.compare==='fertilizer')$('analysis-content').innerHTML=`<div class="analysis-title">比较施肥：F1 · F2 · F3</div><div class="mean-pair">${[0,1,2].map(f=>`<span>F${f+1} <b>${((means[0][f]+means[1][f])/2).toFixed(1)}</b></span>`).join('')}</div><p>在各灌水主区内，比较不同施肥水平。</p>`;else $('analysis-content').innerHTML=`<div class="analysis-title">交互：灌水效应随施肥改变吗？</div><div class="mean-pair">${[0,1,2].map(f=>`<span>F${f+1} <b>+${(means[1][f]-means[0][f]).toFixed(1)}</b></span>`).join('')}</div><p>W2 − W1 并非恒定：该模拟存在交互。</p>`}else{const unit=state.compare==='water'?'主区 · 6 个灌水实验单元':'副区 · 18 个施肥实验单元';$('analysis-content').innerHTML=`<div class="analysis-title">${unit}</div><div class="error-denominator">${den.label} <span>df = ${den.df}</span></div><div class="f-formula">F = ${effect.ms.toFixed(2)} / ${den.ms.toFixed(2)} = <b>${effect.f.toFixed(2)}</b></div><p>${state.compare==='water'?'同主区的副区共享主区误差。':'施肥与 A×B，使用同一个副区误差项。'}</p>`}
 if(state.selected){const d=state.data.find(v=>v.block===state.selected.block&&v.water===state.selected.water&&v.fertilizer===state.selected.fertilizer);$('readout').textContent=`区组 ${d.block+1} · W${d.water+1}F${d.fertilizer+1} · 模拟响应 ${d.value.toFixed(1)}`}
 $('anova-rows').innerHTML=stats.rows.map(r=>`<tr class="${r.id===effect.id?'tested':r.id===den.id?'denominator':''}"><td>${r.label}</td><td>${r.df}</td><td>${r.ms.toFixed(2)}</td><td>${r.f==null?'—':r.f.toFixed(2)}</td></tr>`).join('')}
document.querySelectorAll('[data-effect]').forEach(b=>b.onclick=()=>{state.compare=b.dataset.effect;state.selected=null;update()});
$('random-main').onclick=()=>{stop();state.design=M.randomizeMain(state.design);setStep(2)};$('random-sub').onclick=()=>{stop();state.design=M.randomizeSub(state.design);setStep(3)};
function stop(){auto=false;clearInterval(timer);timer=null;$('play').textContent='▶';$('play').setAttribute('aria-pressed','false');$('play').setAttribute('aria-label','自动演示')}
function play(){if(auto){stop();return}auto=true;if(state.step===c.steps.length-1)setStep(0);world.paused=false;syncMotion();$('play').textContent='Ⅱ';$('play').setAttribute('aria-pressed','true');$('play').setAttribute('aria-label','暂停自动演示');timer=setInterval(()=>{if(state.step===c.steps.length-1){stop();return}setStep(state.step+1)},8500)}
function syncMotion(){$('motion').textContent=world.paused?'▶ 动画':'Ⅱ 动画';$('motion').setAttribute('aria-pressed',String(!world.paused))}
$('play').onclick=play;$('prev').onclick=()=>{stop();setStep(state.step-1)};$('next').onclick=()=>{stop();setStep(state.step+1)};$('motion').onclick=()=>{world.paused=!world.paused;syncMotion();if(world.paused)stop()};$('rotate').onclick=()=>{world.autoRotate=!world.autoRotate;$('rotate').setAttribute('aria-pressed',String(world.autoRotate))};$('front').onclick=()=>{world.autoRotate=false;world.camera.yaw=0;world.camera.pitch=.12;world.camera.zoom=1;$('rotate').setAttribute('aria-pressed','false')};$('tilt').onclick=()=>{world.autoRotate=false;world.camera.pitch=world.camera.pitch>.9?world.initial.pitch:1.18;$('rotate').setAttribute('aria-pressed','false')};$('reset').onclick=()=>{stop();world.resetView();world.paused=false;state.design=M.design(3);state.compare='water';state.selected=null;setStep(0);syncMotion();$('rotate').setAttribute('aria-pressed','false')};$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('fullscreen').textContent='F11 全屏'}};
let down=null;$('scene').addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY}});$('scene').addEventListener('pointerup',e=>{if(state.step<5||!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>7)return;const rect=$('scene').getBoundingClientRect(),x=e.clientX-rect.x,y=e.clientY-rect.y;const nearest=[...state.hitRegions].sort((a,b)=>Math.hypot(x-a.point.x,y-a.point.y)-Math.hypot(x-b.point.x,y-b.point.y))[0];if(nearest&&Math.hypot(x-nearest.point.x,y-nearest.point.y)<Math.max(13,Math.min(48,nearest.point.scale*.72))){state.selected={block:nearest.block,water:nearest.water,fertilizer:nearest.fertilizer};renderAnalysis()}});
document.addEventListener('keydown',e=>{if(['INPUT','BUTTON','A','CANVAS','SUMMARY'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight'){stop();setStep(state.step+1);e.preventDefault()}else if(e.key==='ArrowLeft'){stop();setStep(state.step-1);e.preventDefault()}else if(e.code==='Space'){play();e.preventDefault()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
window.lessonDiagnostics={get state(){return JSON.parse(JSON.stringify(state))},get camera(){return {...world.camera}},get primitives(){return world.items.length},get time(){return world.time},get paused(){return world.paused},get stats(){return JSON.parse(JSON.stringify(stats))}};
setStep(0);syncMotion();
})();


